{"implementation":"def solve(case):
    edges = case['edges']
    communities = case['communities']
    resolution = case['resolution']
    nodes = set(communities.keys())
    adj = {node: {} for node in nodes}
    deg = {node: 0 for node in nodes}
    total_weight = 0
    for u, v, w in edges:
        adj[u][v] = adj[u].get(v, 0) + w
        adj[v][u] = adj[v].get(u, 0) + w
        total_weight += w
        deg[u] += w
        deg[v] += w
    m = total_weight
    if m == 0:
        return {'communities': dict(communities), 'moves': []}
    sum_tot = {}
    for node, comm in communities.items():
        sum_tot[comm] = sum_tot.get(comm, 0) + deg[node]
    current_comm = dict(communities)
    moves = []
    node_order = sorted(communities.keys())
    for node in node_order:
        w_to_c = {}
        for nb, w in adj.get(node, {}).items():
            nb_comm = current_comm[nb]
            w_to_c[nb_comm] = w_to_c.get(nb_comm, 0) + w
        cur = current_comm[node]
        w_to_cur = w_to_c.get(cur, 0)
        deg_i = deg[node]
        best_gain = 0.0
        best_comm = None
        for c, w_to_c_val in w_to_c.items():
            if c == cur:
                continue
            delta = (w_to_c_val - w_to_cur) / m - resolution * deg_i * (sum_tot.get(c, 0) - sum_tot[cur]) / (2 * m * m)
            if delta > 0:
                if best_comm is None or delta > best_gain or (delta == best_gain and c < best_comm):
                    best_gain = delta
                    best_comm = c
        if best_comm is not None:
            moves.append({'from': cur, 'node': node, 'to': best_comm})
            sum_tot[cur] -= deg_i
            sum_tot[best_comm] = sum_tot.get(best_comm, 0) + deg_i
            current_comm[node] = best_comm
    return {'communities': dict(current_comm), 'moves': moves}"}
